//! ⚙️ Configuration workers keep the actual typed source and paid session across original caller turns.
use super::{ArtifactApp,FrameworkConfigurationBinaryJob};
use semio_framework_job::{InteractiveJob,Operation,OriginalTurnFailure,StepContext};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress}};
use semio_framework_job_worker::{MountedWorkerJobSession,WorkerJobPoll};
use semio_framework_plugin_ownership::reserved_job_session::RefusedWorkerSource;
use std::mem::ManuallyDrop;

pub(crate) struct ConfigurationWorker<A:ArtifactApp>{source:Option<RefusedWorkerSource<FrameworkConfigurationBinaryJob<A>>>,session:Option<MountedWorkerJobSession<FrameworkConfigurationBinaryJob<A>>>,binding:semio_framework::action_bus::OriginalToolSourceBinding,operation:Operation,maximum_output:usize,fuel:u64,preparation:RetainedCloneGrant,close:RetainedCloneGrant,checkpoint:u64,outcome_seen:bool,terminal:Option<u8>,closing:bool,failure:ManuallyDrop<Option<OriginalTurnFailure>>,overruns:semio_framework_trace::StepOverrunLedger}
impl<A:ArtifactApp> ConfigurationWorker<A>{
 pub(crate) fn new(job:FrameworkConfigurationBinaryJob<A>,operation:Operation,maximum_output:usize,fuel:u64,preparation:RetainedCloneGrant,close:RetainedCloneGrant,cx:&StepContext<'_>)->Self{Self{source:Some(RefusedWorkerSource::pending(job,(cx.operation(),cx.generation()))),session:None,binding:semio_framework::action_bus::OriginalToolSourceBinding::borrow(cx),operation,maximum_output,fuel,preparation,close,checkpoint:0,outcome_seen:false,terminal:None,closing:false,failure:ManuallyDrop::new(None),overruns:semio_framework_trace::StepOverrunLedger::new()}}
 pub(crate) fn semantic_operation(&self)->Operation{self.operation}
 pub(crate) fn terminal_is_empty(&self)->bool{self.source.is_none()&&self.session.is_none()&&self.failure.is_none()}
 pub(crate) fn take_failure(&mut self)->Option<OriginalTurnFailure>{self.failure.take()}
 pub(crate) fn cancel(&mut self){self.closing=true;}
 fn retain_failure(&mut self,error:OriginalTurnFailure)->Result<(),OriginalTurnFailure>{self.closing=true;if self.failure.is_none(){*self.failure=Some(error);Ok(())}else{Err(error)}}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if self.binding.matches(cx){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration worker refused different original source roots or clock").into())}}
 pub(crate) fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(source)=self.source.as_ref(){return source.retirement_demands(body)}if let Some(session)=self.session.as_ref(){return session.retirement_demands(body).map_err(|error|match error{semio_framework_job_worker::WorkerJobDemandError::Refused(error)=>error,semio_framework_job_worker::WorkerJobDemandError::Contention(_)=>ValueError::literal(ValueRefusalKind::UnsupportedOwner,"original configuration worker close is contended")})}Ok(RetirementDemand{depth:usize::from(self.failure.is_some()),..Default::default()})}
 pub(crate) fn advance(&mut self,cx:&mut StepContext<'_>,cancel:&semio_framework_job::CancelToken)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if cx.is_cancelled()||cancel.is_cancelled_now(){self.closing=true;if self.terminal.is_none(){self.terminal=Some(2)}}
  if self.closing{return self.close_step(cx,cancel)}
  if let Some(source)=self.source.as_mut(){let config=semio_framework_job_worker_authority::BatchDriveConfig{retained:self.preparation,site:"plugin_framework_configuration_route",stage:semio_framework_job::InteractiveStage::InteractiveStep,fuel_per_step:self.fuel,step_budget_us:semio_framework_job::INTERACTIVE_LANE_WALL_US};match source.admit_pending(config,cx){Ok(Some(session))=>{self.session=Some(session);assert!(source.terminal_is_empty());self.source.take();},Ok(None)=>{},Err(error)=>self.retain_failure(error)?}return Ok(false)}
  let Some(session)=self.session.as_mut()else{return Ok(true)};
  let result=(||->Result<(),OriginalTurnFailure>{
   if !self.outcome_seen{let cores=std::thread::available_parallelism().map_or(1,std::num::NonZeroUsize::get);let pool=semio_framework_async::process_worker_pool(semio_framework_async::WorkerPoolConfig::new(semio_framework_async::ProcessKind::InteractiveNative,cores));let poll=match session.pump_one(&pool,semio_framework_async::Lane::Interactive,self.preparation){Ok(poll)=>poll,Err(fault)if super::reserved_pump_fault_is_transient(&fault)=>return Ok(()),Err(_)=>return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration worker lost its original pump transition").into())};if !matches!(poll,WorkerJobPoll::Outcome|WorkerJobPoll::Terminal){#[cfg(target_arch="wasm32")]if let Some(now)=semio_framework_job::default_now_ms(){pool.pump(now);}return Ok(())}
    let(issued,receipt)=session.take_checked_out_retained_step_receipt().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration worker lost its exact outcome receipt"))?;if !receipt.fits(issued){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration worker exceeded its issued receipt").into())}
    let view=session.checked_out_outcome().map_err(|_|ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration outcome custody was refused"))?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration outcome is absent"))?;
    self.terminal=match &view{semio_framework_job::JobOutcomeView::CheckpointReady{state,applied_progress,..}=>{if *applied_progress<self.checkpoint||state.len()>self.maximum_output{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration checkpoint violates its exact execution contract").into())}self.checkpoint=*applied_progress;None},semio_framework_job::JobOutcomeView::Complete{output,..}=>{if output.is_some_and(|output|output.len()!=0){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration worker returned an unexpected output envelope").into())}Some(1)},semio_framework_job::JobOutcomeView::Cancelled{..}=>Some(2),semio_framework_job::JobOutcomeView::Fault{..}=>Some(3),_=>None};drop(view);
    if session.callback_verdict().copied().is_some_and(|verdict|self.overruns.admit(&verdict).is_terminal()){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration worker exceeded its callback wall budget").into())}
    self.outcome_seen=true;if self.terminal.is_some(){self.closing=true;return Ok(())}
   }
   let grant=Self::bounded(cx.retained_grant(),self.close);if cx.should_yield()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(())}let step=session.acknowledge_checked_out_outcome(grant);let progress=step.progress();cx.consume_retained(progress)?;cx.consume_fuel(progress.copied_items as u64);if session.checked_out_outcome_descriptor().is_none(){session.resume().map_err(|_|ValueError::literal(ValueRefusalKind::InvariantViolated,"configuration worker lost exact resume authority"))?;self.outcome_seen=false;}Ok(())
  })();if let Err(error)=result{self.retain_failure(error)?}Ok(false)
 }
 fn bounded(current:RetainedCloneGrant,policy:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:current.maximum_items.min(policy.maximum_items),maximum_copy_bytes:current.maximum_copy_bytes.min(policy.maximum_copy_bytes),maximum_capacity_bytes:current.maximum_capacity_bytes.min(policy.maximum_capacity_bytes),maximum_release_bytes:current.maximum_release_bytes.min(policy.maximum_release_bytes),maximum_depth:current.maximum_depth.min(policy.maximum_depth)}}
 pub(crate) fn close_step(&mut self,cx:&mut StepContext<'_>,cancel:&semio_framework_job::CancelToken)->Result<bool,OriginalTurnFailure>{let loan=Self::bounded(cx.retained_grant(),self.close);cx.with_retained_loan(loan,|same|self.close_body(same,cancel))}
 fn close_body(&mut self,cx:&mut StepContext<'_>,cancel:&semio_framework_job::CancelToken)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;self.closing=true;if let Some(source)=self.source.as_mut(){if source.terminal_is_empty(){self.source.take();return Ok(false)}source.close_step(cx)?;return Ok(false)}
  if let Some(session)=self.session.as_mut(){session.begin_close();let grant=cx.retained_grant();if matches!(session.has_original_cancel_alias_witness(cancel),Ok(true)){match session.return_original_cancel_alias_step(cancel,grant){Ok(_)|Err(semio_framework_job_worker::WorkerJobDemandError::Contention(_))=>return Ok(false),Err(semio_framework_job_worker::WorkerJobDemandError::Refused(error))=>return Err(error.into())}}
   match session.close_step(cx)?{semio_framework_job_worker_authority::WorkerJobCloseStep::Complete{..}if session.terminal_is_empty()=>{self.session.take();},_=>{}}return Ok(false)}
  if self.failure.is_none()&&self.terminal!=Some(1){*self.failure=Some(ValueError::literal(if self.terminal==Some(2){ValueRefusalKind::Canceled}else{ValueRefusalKind::InvariantViolated},"configuration worker ended without its admitted successful outcome").into())}Ok(true)
 }
}
impl<A:ArtifactApp> Drop for ConfigurationWorker<A>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"configuration source or session dropped before original paid close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.failure)}}}}
